import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'

import { logsViewerFiltersLogic } from 'products/logs/frontend/components/LogsViewer/Filters/logsViewerFiltersLogic'

import type { UniversalFiltersGroup } from '../../../../../../frontend/src/types'
import { cycleFacetValue, facetFilterTarget } from './facetFilters'
import { FacetSource } from './facets'

export interface FacetRailLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface facetRailLogicValues {
    collapsedFacets: string[]
    facetNameSearch: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface facetRailLogicActions {
    setFilterGroup: (
        filterGroup: UniversalFiltersGroup,
        openFilterOnInsert?: boolean | undefined
    ) => {
        filterGroup: UniversalFiltersGroup
        openFilterOnInsert: boolean
    } // logsViewerFiltersLogic
    setFacetNameSearch: (search: string) => {
        search: string
    }
    toggleFacetCollapsed: (facetKey: string) => {
        facetKey: string
    }
    toggleFacetValue: (
        source: FacetSource,
        value: string
    ) => {
        source: FacetSource
        value: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface facetRailLogicMeta {
    key: string
}

export type facetRailLogicType = MakeLogicType<
    facetRailLogicValues,
    facetRailLogicActions,
    FacetRailLogicProps,
    facetRailLogicMeta
>

// The rail is a lens over the existing filter model — facet toggles write straight back to
// logsViewerFiltersLogic's reducers, so URL sync, saved views, and the chips bar stay in step.
export const facetRailLogic = kea<facetRailLogicType>([
    path(['products', 'logs', 'frontend', 'components', 'LogsViewer', 'FacetRail', 'facetRailLogic']),
    props({ id: 'default' } as FacetRailLogicProps),
    key((props) => props.id),

    connect((props: FacetRailLogicProps) => ({
        actions: [logsViewerFiltersLogic({ id: props.id }), ['setFilterGroup']],
    })),

    actions({
        // Generic toggle: the rail is config-driven, so a single action cycles a value through
        // whichever filterGroup property filter the facet's source maps to (see FacetConfig.source).
        toggleFacetValue: (source: FacetSource, value: string) => ({ source, value }),
        toggleFacetCollapsed: (facetKey: string) => ({ facetKey }),
        // Free-text filter over the facet *fields* shown in the rail (not their values). URL-synced by
        // logsSceneLogic on the main scene, so deliberately not persisted here.
        setFacetNameSearch: (search: string) => ({ search }),
    }),

    reducers({
        facetNameSearch: [
            '',
            {
                setFacetNameSearch: (_, { search }) => search,
            },
        ],
        collapsedFacets: [
            [] as string[],
            { persist: true },
            {
                toggleFacetCollapsed: (state, { facetKey }) =>
                    state.includes(facetKey) ? state.filter((k) => k !== facetKey) : [...state, facetKey],
            },
        ],
    }),

    listeners(({ props, actions }) => ({
        toggleFacetValue: ({ source, value }) => {
            // Both polarities live in the filterGroup under the facet's own key, so a click is one
            // write: the value cycles included → excluded → cleared, and the chips bar shows each
            // step. Filters on the same key the facet doesn't own (any operator other than exact or
            // is_not) are left alone.
            const { filterGroup } = logsViewerFiltersLogic({ id: props.id }).values
            actions.setFilterGroup(cycleFacetValue(filterGroup, facetFilterTarget(source), value), false)
        },
    })),
])
